const countryDialog=document.getElementById('countryDialog'),countryBrief=document.getElementById('countryBrief'),atlas=document.getElementById('atlasGrid');
const countryAliases={'Congo, Democratic Republic':'Democratic Republic of the Congo','Congo, Republic':'Republic of the Congo','Côte d’Ivoire':'Ivory Coast','Gambia':'The Gambia'};
const adviceSlugs={'Congo, Democratic Republic':'democratic-republic-of-the-congo','Congo, Republic':'republic-of-the-congo','Côte d’Ivoire':'cote-d-ivoire','Gambia':'the-gambia','São Tomé and Príncipe':'sao-tome-and-principe'};
function safeText(value,fallback='Not available'){return String(value||fallback).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function adviceSlug(country){return adviceSlugs[country]||country.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/&/g,'and').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'')}
function readableDate(value){if(!value)return 'Publication date unavailable';const d=new Date(value);return Number.isNaN(d.valueOf())?'Publication date unavailable':d.toLocaleDateString(undefined,{day:'numeric',month:'short',year:'numeric'})}
function plainSummary(value){const text=String(value||'').replace(/<[^>]+>/g,' ').replace(/&nbsp;/g,' ').replace(/&amp;/g,'&').replace(/\s+/g,' ').trim();return text.length>520?`${text.slice(0,517)}…`:text}
function markCountryCards(){atlas.querySelectorAll('.country-card').forEach(card=>{card.tabIndex=0;card.setAttribute('role','button');card.setAttribute('aria-label',`Open pocketbook entry for ${card.querySelector('h3')?.textContent}`)})}
new MutationObserver(markCountryCards).observe(atlas,{childList:true});markCountryCards();
atlas.addEventListener('click',event=>{const card=event.target.closest('.country-card');if(card)openCountryBrief(card.querySelector('h3').textContent)});
atlas.addEventListener('keydown',event=>{if((event.key==='Enter'||event.key===' ')&&event.target.matches('.country-card')){event.preventDefault();openCountryBrief(event.target.querySelector('h3').textContent)}});
document.querySelector('.country-close').addEventListener('click',()=>countryDialog.close());
async function getJson(url){const response=await fetch(url);if(!response.ok)throw new Error(`${response.status}`);return response.json()}
async function openCountryBrief(country){
 countryDialog.showModal();countryBrief.innerHTML='<p class="database-status">Checking official and reference sources…</p>';
 const lookup=countryAliases[country]||country,atlasRow=(window.africanAtlas||[]).find(row=>row[0]===country),slug=adviceSlug(country),checkedAt=new Date();
 try{
  const countryResults=await getJson(`https://restcountries.com/v3.1/name/${encodeURIComponent(lookup)}?fullText=true`),countryData=countryResults[0],code=countryData.cca2;
  const [populationResult,adviceResult]=await Promise.allSettled([getJson(`https://api.worldbank.org/v2/country/${code}/indicator/SP.POP.TOTL?format=json&mrnev=1`),getJson(`https://www.gov.uk/api/content/foreign-travel-advice/${slug}`)]);
  const populationRow=populationResult.status==='fulfilled'?populationResult.value?.[1]?.[0]:null,advice=adviceResult.status==='fulfilled'?adviceResult.value:null;
  const population=populationRow?.value||countryData.population,capital=(countryData.capital||[]).join(', '),currencies=Object.values(countryData.currencies||{}).map(item=>item.name).join(', '),languages=Object.values(countryData.languages||{}).join(', '),callingCode=(countryData.idd?.root||'')+(countryData.idd?.suffixes?.[0]||'');
  const adviceDate=advice?.public_updated_at||advice?.details?.public_updated_at,adviceSummary=plainSummary(advice?.details?.change_description),ukAdvice=`https://www.gov.uk/foreign-travel-advice/${slug}`,usSearch=`https://travel.state.gov/content/travel/en/search.html?search_input=${encodeURIComponent(country)}`,whoProfile=`https://www.who.int/countries/${code.toLowerCase()}/`;
  countryBrief.innerHTML=`<div class="country-hero"><p class="eyebrow">AFRICAN SAFARI POCKETBOOK</p><h2>${safeText(country)}</h2><p>${safeText(countryData.region)} · ${safeText(countryData.subregion)}</p><div class="source-status"><span></span>Sources checked ${readableDate(checkedAt)}</div></div><section class="entry-section"><div class="entry-kicker">REFERENCE</div><h3>Country essentials</h3><div class="country-facts"><div><small>Capital</small><strong>${safeText(capital)}</strong></div><div><small>Population</small><strong>${Number(population).toLocaleString()}</strong><em>${populationRow?`World Bank · ${safeText(populationRow.date)}`:'Reference estimate'}</em></div><div><small>Currency</small><strong>${safeText(currencies)}</strong></div><div><small>Languages</small><strong>${safeText(languages)}</strong></div><div><small>Driving side</small><strong>${safeText(countryData.car?.side)}</strong></div><div><small>Calling code</small><strong>${safeText(callingCode)}</strong></div></div><p class="source-note">General country fields are reference data and may lag official changes. Population uses the latest available World Bank observation where returned.</p></section><section class="entry-section"><div class="entry-kicker">DISCOVER</div><h3>Safari and nature highlights</h3><p>${safeText(atlasRow?.[2],'Destination information is being expanded.')}</p><p class="editorial-label">Curated Pocketbook index · Confirm access, permits, seasonality and operating status locally.</p></section><section class="entry-section advisory-section"><div class="entry-kicker live">LIVE ADVISORY</div><h3>Political and security context</h3>${advice?`<div class="advisory-update"><strong>UK government travel advice</strong><small>Published or updated ${readableDate(adviceDate)}</small><p>${safeText(adviceSummary,'Open the current advisory for security, political and entry information.')}</p></div>`:`<div class="advisory-unavailable"><strong>Official advisory could not be retrieved</strong><p>Do not rely on cached or general descriptions for current political and security conditions. Open an official source before travel.</p></div>`}<div class="advisory-links"><a href="${ukAdvice}" target="_blank" rel="noopener">UK travel advice ↗</a><a href="${usSearch}" target="_blank" rel="noopener">US travel advisory ↗</a></div></section><section class="entry-section"><div class="entry-kicker">HEALTH</div><h3>Health preparation</h3><p>Health requirements and outbreak conditions can change. Consult an authorised travel-health professional and current official guidance.</p><div class="source-links"><a href="${whoProfile}" target="_blank" rel="noopener">WHO country profile ↗</a><a href="https://www.who.int/emergencies/disease-outbreak-news" target="_blank" rel="noopener">WHO outbreak notices ↗</a></div></section><div class="source-register"><strong>Source register</strong><span>World Bank: population</span><span>GOV.UK FCDO: live travel advisory</span><span>WHO: country health and outbreak links</span><span>REST Countries: general reference fields</span><small>Retrieved ${checkedAt.toLocaleString()}. Entry and visa rules must be confirmed with the destination country’s immigration authority or embassy.</small></div>`;
 }catch(error){
  countryBrief.innerHTML=`<div class="country-hero"><p class="eyebrow">AFRICAN SAFARI POCKETBOOK</p><h2>${safeText(country)}</h2><div class="source-status offline"><span></span>Offline entry</div></div><section class="entry-section"><div class="entry-kicker">DISCOVER</div><h3>Safari and nature highlights</h3><p>${safeText(atlasRow?.[2])}</p></section><section class="entry-section advisory-section"><div class="entry-kicker live">CURRENT CONDITIONS</div><h3>Connect before relying on this entry</h3><p>Live country facts and official travel advice are unavailable. The destination index remains available offline, but it is not a substitute for current immigration, health or security information.</p><a class="retry-brief" href="#">Try live sources again</a></section>`;
  countryBrief.querySelector('.retry-brief')?.addEventListener('click',event=>{event.preventDefault();openCountryBrief(country)});
 }
}
